# Coroutines v2 · Phần 3 · CH Channel và select (Deep Dive, "Channel" tr. PDF 235–256 và "Select" tr. 257–262) + sim coroutines.chan.

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)
    m = lambda k, vi, en=None: a('m.chan.' + k, vi, en)

    # ---------------- sim coroutines.chan ----------------
    m('title', 'Channel: producer nhanh, consumer chậm, sức chứa khác nhau', 'Channel: a fast producer, a slow consumer, different capacities')
    m('overview', 'Producer gửi 5 phần tử, mỗi lần cách 100 ms; consumer chờ 1 giây rồi nhận từng phần tử, mỗi phần tử xử lý 1 giây. Chọn sức chứa ở ô "Loại channel" rồi bấm Step: để ý producer bị suspend ở `send` khi nào, buffer chứa bao nhiêu, và phần tử nào bị mất.', 'The producer sends 5 elements, 100 ms apart; the consumer waits 1 second, then receives elements one by one, spending 1 second on each. Pick a capacity in "Channel kind" and press Step: watch when the producer suspends at `send`, how many elements the buffer holds, and which elements get lost.')
    m('wrapup', 'Sức chứa quyết định ai phải chờ ai. RENDEZVOUS (0): mỗi lần gửi phải "gặp mặt" người nhận, producer chờ từng lần. Buffer 3: producer chạy trước tới khi đầy. UNLIMITED: producer không bao giờ chờ (nhưng bộ nhớ có thể phình). CONFLATED: chỉ giữ phần tử mới nhất. DROP_OLDEST: buffer đầy thì bỏ phần tử cũ nhất. Mọi phần tử chỉ được nhận MỘT lần.', 'Capacity decides who waits for whom. RENDEZVOUS (0): every send must "meet" a receiver, so the producer waits each time. Buffer 3: the producer runs ahead until the buffer is full. UNLIMITED: the producer never waits (but memory can grow). CONFLATED: only the newest element is kept. DROP_OLDEST: when full, the oldest element is dropped. Every element is received only ONCE.')
    m('simp.1', 'Thời gian là của mã (ms), hiển thị để so sánh; thứ tự trong cùng một mốc: producer trước, consumer sau. Thư viện thật có thể xen kẽ khác ở các mốc trùng nhau.', 'Times are the code\'s (ms), shown for comparison; within the same instant the producer goes first, then the consumer. The real library may interleave differently at identical instants.')
    m('ctl.hint', 'Mỗi lựa chọn là một sức chứa trong sách; so thứ tự "Sent" và các số nhận được.', 'Each option is a capacity from the book; compare the order of "Sent" lines and the numbers received.')
    m('ctl.mode', 'Loại channel', 'Channel kind')
    for k, vi, en in [('rendezvous', 'RENDEZVOUS (0, mặc định)', 'RENDEZVOUS (0, default)'), ('buffered', 'capacity = 3', 'capacity = 3'), ('unlimited', 'UNLIMITED', 'UNLIMITED'),
                      ('conflated', 'CONFLATED', 'CONFLATED'), ('dropOldest', 'capacity 2 + DROP_OLDEST', 'capacity 2 + DROP_OLDEST')]:
        m('ctl.mode.' + k, vi, en)
        m('scope.' + k, vi, en)
    m('diagramTitle', 'Producer, buffer, consumer theo thời gian', 'Producer, buffer and consumer over time')
    m('diagramDesc', 'Ba hàng: producer, số phần tử trong channel, consumer', 'Three rows: producer, elements in the channel, consumer')
    m('n.prod', 'Producer (produce)', 'Producer (produce)')
    m('n.chan', 'Buffer của channel', 'Channel buffer')
    m('n.cons', 'Consumer (for)', 'Consumer (for)')
    m('lanes.ch', 'Channel', 'Channel')
    m('axis', 'ms (thời gian của mã) →', 'ms (code time) →')
    m('col.mode', 'Loại channel', 'Channel kind')
    m('met.n', 'Phần tử trong buffer', 'Elements in buffer')
    m('met.sent', 'Đã gửi', 'Sent')
    m('met.recv', 'Đã nhận', 'Received')
    m('met.dropped', 'Bị mất', 'Lost')
    m('bar.run', 'đang chạy / xử lý', 'running / processing')
    m('bar.wait', 'suspend chờ (send đầy, hoặc receive rỗng)', 'suspended (send on full, or receive on empty)')
    m('bar.ready', 'phần tử nằm trong buffer (số = bao nhiêu)', 'elements in the buffer (number = how many)')
    for k, vi, en in [('suspended', 'chờ ở send', 'waiting at send'), ('waiting', 'chờ phần tử', 'waiting for element'), ('start', 'delay(1000) đầu', 'initial delay(1000)'), ('process', 'xử lý 1 s', 'processing 1 s')]:
        m('lbl.' + k, vi, en)
    S = [
        ('buffered', 'send({v}): vào buffer', 'send({v}): into the buffer', 'Buffer còn chỗ, nên `send` trả về ngay và phần tử nằm chờ trong channel (buffer: {n}).', 'The buffer has room, so `send` returns immediately and the element waits in the channel (buffer: {n}).'),
        ('full', 'send({v}): suspend, chưa có chỗ', 'send({v}): suspends, no room', 'Không có chỗ (buffer đầy, hoặc RENDEZVOUS không có buffer) và chưa ai đang chờ nhận, nên producer suspend ngay tại `send`.', 'There is no room (the buffer is full, or RENDEZVOUS has no buffer) and nobody is waiting to receive, so the producer suspends right at `send`.'),
        ('resumed', 'Có chỗ: producer resume, {v} vào buffer', 'Room appears: the producer resumes, {v} enters the buffer', 'Consumer vừa lấy một phần tử, nên `send` đang chờ hoàn tất.', 'The consumer just took an element, so the waiting `send` completes.'),
        ('handover', 'Gặp mặt: {v} trao thẳng cho consumer', 'Rendezvous: {v} handed straight to the consumer', 'Consumer tới nhận khi producer đang chờ ở `send`: phần tử đi thẳng từ người gửi sang người nhận, producer được resume.', 'The consumer arrives while the producer waits at `send`: the element goes straight from sender to receiver, and the producer resumes.'),
        ('sentLine', 'producer in "Sent"', 'the producer prints "Sent"', 'Sau `delay(100)`, producer in "Sent" rồi sang phần tử kế.', 'After `delay(100)`, the producer prints "Sent" and moves on to the next element.'),
        ('closed', 'produce kết thúc: channel đóng', 'produce finishes: the channel closes', '`produce` tự `close()` channel khi khối kết thúc, nên vòng `for` của consumer sẽ dừng sau khi lấy hết.', '`produce` calls `close()` on the channel itself when its block ends, so the consumer\'s `for` loop stops after draining it.'),
        ('got', 'consumer nhận {v}', 'the consumer receives {v}', 'Consumer lấy phần tử đầu hàng (FIFO), in ra, rồi `delay(1000)`.', 'The consumer takes the first element in line (FIFO), prints it, then `delay(1000)`.'),
        ('waiting', 'consumer chờ: channel rỗng', 'the consumer waits: the channel is empty', '`receive` suspend vì chưa có phần tử và channel chưa đóng.', '`receive` suspends because there is no element and the channel is not closed.'),
        ('end', 'vòng for kết thúc', 'the for loop ends', 'Channel đã đóng và rỗng: vòng `for` thoát bình thường.', 'The channel is closed and empty: the `for` loop exits normally.'),
        ('replaced', 'CONFLATED: {v} bị thay', 'CONFLATED: {v} is replaced', 'Buffer cỡ 1: phần tử mới thay phần tử cũ chưa ai nhận. Phần tử cũ mất.', 'Buffer of size 1: the new element replaces the old, unreceived one. The old one is lost.'),
        ('droppedOld', 'DROP_OLDEST: bỏ {v}', 'DROP_OLDEST: {v} is dropped', 'Buffer đầy: phần tử cũ nhất bị bỏ để chừa chỗ cho phần tử mới; `send` không suspend.', 'The buffer is full: the oldest element is dropped to make room for the new one; `send` does not suspend.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('rendezvous', 'RENDEZVOUS: không có buffer, nên mỗi `send` phải chờ một `receive`, giống một điểm hẹn đổi sách (không phải giá sách).', 'RENDEZVOUS: no buffer, so every `send` must wait for a `receive`, like a book-swap meeting point (not a bookshelf).'),
        ('full', 'Back-pressure: buffer đầy làm producer chậm lại cho kịp consumer, thay vì làm tràn bộ nhớ.', 'Back-pressure: a full buffer slows the producer down to the consumer\'s pace instead of exhausting memory.'),
        ('conflated', 'Phần tử bị thay thì mất hẳn. Hợp với "chỉ cần giá trị mới nhất" (vị trí GPS, tiến độ), không hợp khi mọi phần tử đều quan trọng.', 'A replaced element is gone for good. Fine for "only the latest value matters" (GPS position, progress), wrong when every element matters.'),
        ('dropOldest', 'CONFLATED chính là capacity 1 + DROP_OLDEST.', 'CONFLATED is exactly capacity 1 + DROP_OLDEST.'),
        ('produce', 'Không phải nhớ `close()`: `produce` đóng channel dù khối kết thúc bình thường, bị hủy hay lỗi.', 'No need to remember `close()`: `produce` closes the channel whether the block ends normally, is cancelled, or fails.')]:
        m('co.' + k, vi, en)
    a('cap.chan', 'Ba hàng theo thời gian của mã: producer (liền = đang chạy, viền đứt = suspend ở send), buffer (số trên thanh = số phần tử đang nằm trong channel; dấu ✕ = phần tử bị mất), consumer (mốc = phần tử vừa nhận). Đổi "Loại channel" và so hình dạng.', 'Three rows over code time: the producer (solid = running, dashed = suspended at send), the buffer (the number on the bar = elements sitting in the channel; ✕ = a lost element), the consumer (a marker = the element just received). Change "Channel kind" and compare the shapes.')
    a('ch.sim.coroutines.chan', 'Sức chứa', 'Capacity')

    # ---------------- chương CH ----------------
    C = 'ch'
    a(C + '.title', 'Channel và select: giao tiếp giữa các coroutine', 'Channel and select: communication between coroutines')
    a(C + '.essence',
      '`Channel` là công cụ để các coroutine gửi dữ liệu cho nhau. Hình dung một giá sách trao đổi công cộng: người này đặt sách lên, người kia tới lấy. Bao nhiêu người gửi, người nhận cũng được, và mỗi phần tử chỉ được nhận đúng MỘT lần.\n'
      '`send` và `receive` đều là hàm suspend: nhận khi channel rỗng thì chờ; gửi khi hết chỗ thì chờ. Sức chứa quyết định ai chờ ai: RENDEZVOUS (0, mặc định), số cụ thể, BUFFERED (64), UNLIMITED, CONFLATED (chỉ giữ cái mới nhất), cộng `onBufferOverflow` (SUSPEND, DROP_OLDEST, DROP_LATEST).\n'
      'Builder `produce { }` tạo channel và tự đóng nó khi xong, nên an toàn hơn tự `close()`. Channel dùng cho fan-out, fan-in, pipeline. `select` chờ cái nào xong trước (race giữa các `async`, nhận từ channel nào có dữ liệu trước). Ngày nay channel thường được dùng gián tiếp qua `Flow` (`channelFlow`, `callbackFlow`).',
      '`Channel` is a tool for coroutines to send data to each other. Picture a public book-swap shelf: one person puts a book on it, another comes and takes it. There can be any number of senders and receivers, and each element is received exactly ONCE.\n'
      '`send` and `receive` are both suspending: receiving from an empty channel waits; sending when there is no room waits. Capacity decides who waits for whom: RENDEZVOUS (0, the default), a number, BUFFERED (64), UNLIMITED, CONFLATED (keeps only the newest), plus `onBufferOverflow` (SUSPEND, DROP_OLDEST, DROP_LATEST).\n'
      'The `produce { }` builder creates a channel and closes it when done, which is safer than calling `close()` yourself. Channels are used for fan-out, fan-in and pipelines. `select` waits for whichever finishes first (a race between `async`s, receiving from whichever channel has data first). Nowadays channels are often used indirectly through `Flow` (`channelFlow`, `callbackFlow`).')
    a(C + '.goal.g1', 'Đã thấy producer bị suspend ở send', 'Saw the producer suspend at send')
    a(C + '.goal.g2', 'Đã đi hết mô phỏng (nên thử cả CONFLATED)', 'Went through the whole simulation (also try CONFLATED)')

    S = 'recap'
    a(C + '.sec.%s.title' % S, 'Ôn nhanh: suspend khi chờ', 'Quick review: suspending while waiting')
    B(C, S, 1, 'ask', 'Một coroutine đang chờ dữ liệu bằng hàm suspend có giữ luồng không? Ai sẽ resume nó?', 'Does a coroutine waiting for data in a suspending function hold a thread? Who resumes it?')
    B(C, S, 1, 'ans', 'Không giữ luồng; continuation của nó được cất lại. Ai cung cấp dữ liệu thì resume nó. Với channel, đó là coroutine gọi `send` (hoặc phía nhận, khi producer đang chờ chỗ trống).', 'It holds no thread; its continuation is stored. Whoever provides the data resumes it. With channels, that is the coroutine calling `send` (or the receiving side, when the producer is waiting for room).')

    S = 'basics'
    a(C + '.sec.%s.title' % S, 'Channel: SendChannel + ReceiveChannel', 'Channel: SendChannel + ReceiveChannel')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'kt', 'interface SendChannel<in E> {\n    suspend fun send(element: E)\n    fun close(): Boolean\n}\n\ninterface ReceiveChannel<out E> {\n    suspend fun receive(): E\n    fun cancel(cause: CancellationException? = null)\n}\n\ninterface Channel<E> : SendChannel<E>, ReceiveChannel<E>')
    B(C, S, 2, 'p', '`Channel` hiện thực cả hai interface; nhờ tách đôi, bạn có thể chỉ để lộ `ReceiveChannel` hoặc `SendChannel` để giới hạn cửa ra vào. Hàm suspend là điểm mấu chốt: `receive` trên channel rỗng thì suspend tới khi có phần tử (người tới giá sách mà giá trống thì chờ); `send` khi channel hết sức chứa thì suspend tới khi có chỗ. Trong hàm không suspend thì dùng `trySend`/`tryReceive` (trả về `ChannelResult` ngay), chỉ hợp với channel có sức chứa ([[src:kx-channel]]).', '`Channel` implements both interfaces; thanks to the split, you can expose only `ReceiveChannel` or `SendChannel` to restrict the entry points. Suspension is the key: `receive` on an empty channel suspends until an element arrives (someone at an empty shelf waits); `send` on a channel at capacity suspends until there is room. From non-suspending code use `trySend`/`tryReceive` (returning a `ChannelResult` immediately), which only make sense for channels with capacity ([[src:kx-channel]]).')
    B(C, S, 3, 'kt', 'suspend fun main(): Unit = coroutineScope {\n    val channel = Channel<Int>()\n    launch {\n        repeat(5) { index ->\n            delay(1000)\n            println("Producing next one")\n            channel.send(index * 2)\n        }\n        channel.close()                 // không close thì consumer chờ mãi\n    }\n    launch {\n        for (element in channel) println(element)   // dừng khi channel đóng và rỗng\n    }\n}', 'suspend fun main(): Unit = coroutineScope {\n    val channel = Channel<Int>()\n    launch {\n        repeat(5) { index ->\n            delay(1000)\n            println("Producing next one")\n            channel.send(index * 2)\n        }\n        channel.close()                 // without close the consumer waits forever\n    }\n    launch {\n        for (element in channel) println(element)   // stops when the channel is closed and empty\n    }\n}')
    B(C, S, 4, 'p', 'Dễ quên `close()`, nhất là khi có exception: producer dừng vì lỗi và consumer chờ mãi. `produce { }` là coroutine builder trả về `ReceiveChannel` và đóng channel bất cứ khi nào coroutine kết thúc (xong, bị dừng, bị hủy), nên an toàn và tiện hơn nhiều ([[src:kx-produce]]).', 'It is easy to forget `close()`, especially when an exception happens: the producer stops on an error and the consumer waits forever. `produce { }` is a coroutine builder returning a `ReceiveChannel` that closes the channel whenever the coroutine ends (finished, stopped, cancelled), so it is much safer and more convenient ([[src:kx-produce]]).')
    B(C, S, 5, 'kt', 'fun CoroutineScope.produceNumbers(max: Int): ReceiveChannel<Int> = produce {\n    var x = 0\n    while (x < max) send(x++)\n}')

    S = 'types'
    a(C + '.sec.%s.title' % S, 'Bốn loại channel theo sức chứa, và onBufferOverflow', 'Four channel kinds by capacity, and onBufferOverflow')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p',
      '• Unlimited (`Channel.UNLIMITED`): buffer không giới hạn, `send` không bao giờ suspend.\n'
      '• Buffered: sức chứa cụ thể, hoặc `Channel.BUFFERED` (mặc định 64, đổi bằng system property `kotlinx.coroutines.channels.defaultBuffer` trên JVM).\n'
      '• Rendezvous (mặc định, 0): trao đổi chỉ xảy ra khi người gửi và người nhận "gặp nhau".\n'
      '• Conflated (`Channel.CONFLATED`): buffer cỡ 1, phần tử mới thay phần tử cũ.\n'
      '`onBufferOverflow` quyết định làm gì khi buffer đầy: `SUSPEND` (mặc định), `DROP_OLDEST`, `DROP_LATEST`. CONFLATED = sức chứa 1 + `DROP_OLDEST`. `produce` không cho đặt `onBufferOverflow`, nên khi cần thì tạo bằng hàm `Channel(capacity, onBufferOverflow)`. Ngoài ra `onUndeliveredElement` được gọi khi một phần tử không tới được người nhận (thường vì channel bị đóng/hủy), dùng để đóng tài nguyên được gửi qua channel.',
      '• Unlimited (`Channel.UNLIMITED`): an unbounded buffer; `send` never suspends.\n'
      '• Buffered: a concrete capacity, or `Channel.BUFFERED` (64 by default, overridable with the `kotlinx.coroutines.channels.defaultBuffer` system property on the JVM).\n'
      '• Rendezvous (the default, 0): an exchange happens only when sender and receiver "meet".\n'
      '• Conflated (`Channel.CONFLATED`): a buffer of size 1 where each new element replaces the previous one.\n'
      '`onBufferOverflow` decides what happens when the buffer is full: `SUSPEND` (default), `DROP_OLDEST`, `DROP_LATEST`. CONFLATED = capacity 1 + `DROP_OLDEST`. `produce` does not let you set `onBufferOverflow`, so when you need it, create the channel with the `Channel(capacity, onBufferOverflow)` function. There is also `onUndeliveredElement`, called when an element cannot reach a receiver (usually because the channel was closed/cancelled), used to close resources sent through the channel.')
    B(C, S, 2, 'predict', 'Producer nhanh (gửi mỗi 100 ms, 5 phần tử 0, 2, 4, 6, 8), consumer chậm (bắt đầu sau 1 s, mỗi phần tử 1 s). Consumer nhận được những số nào với: (a) RENDEZVOUS, (b) CONFLATED, (c) capacity 2 + DROP_OLDEST? Với capacity 3, có bao nhiêu dòng "Sent" trước khi consumer in số đầu tiên?', 'A fast producer (sends every 100 ms: 0, 2, 4, 6, 8), a slow consumer (starts after 1 s, 1 s per element). Which numbers does the consumer receive with: (a) RENDEZVOUS, (b) CONFLATED, (c) capacity 2 + DROP_OLDEST? With capacity 3, how many "Sent" lines appear before the consumer prints its first number?')
    B(C, S, 2, 'ans', '(a) cả 5 số, nhưng producer chờ từng lần. (b) chỉ 8: mỗi phần tử mới thay phần tử trước. (c) 6 và 8: hai phần tử cũ nhất bị bỏ dần. Capacity 3: 3 dòng "Sent" (0, 2, 4 vào buffer; lần gửi 6 bị suspend tới khi consumer lấy 0). Bấm Step trong mô phỏng ngay dưới để kiểm từng chế độ.', '(a) all 5, but the producer waits each time. (b) only 8: each new element replaces the previous one. (c) 6 and 8: the two oldest get dropped along the way. Capacity 3: 3 "Sent" lines (0, 2, 4 go into the buffer; sending 6 suspends until the consumer takes 0). Step through the simulation just below to check each mode.')

    S = 'fan'
    a(C + '.sec.%s.title' % S, 'Fan-out, fan-in, pipeline', 'Fan-out, fan-in, pipelines')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Fan-out: nhiều coroutine nhận từ MỘT channel. Dùng vòng `for` (không dùng `consumeEach` từ nhiều coroutine, vì nó hủy channel khi xong). Phần tử được chia công bằng: channel giữ hàng đợi FIFO các coroutine đang chờ, nên nhận lần lượt 0, 1, 2, 0, 1, 2… (như trẻ xếp hàng nhận kẹo, nhận xong quay về cuối hàng). Fan-in: nhiều coroutine gửi vào MỘT channel; có thể gộp nhiều channel bằng `produce` + một `launch` cho mỗi channel nguồn. Pipeline: channel này tạo ra phần tử dựa trên channel kia.', 'Fan-out: several coroutines receive from ONE channel. Use a `for` loop (not `consumeEach` from several coroutines, since it cancels the channel when done). Elements are distributed fairly: the channel keeps a FIFO queue of waiting coroutines, so they receive in turn 0, 1, 2, 0, 1, 2… (like kids queuing for candy and going back to the end of the line). Fan-in: several coroutines send into ONE channel; you can merge channels with `produce` + one `launch` per source channel. Pipeline: one channel produces elements based on another.')
    B(C, S, 2, 'kt', 'fun <T> CoroutineScope.fanIn(channels: List<ReceiveChannel<T>>): ReceiveChannel<T> = produce {\n    for (channel in channels) {\n        launch { for (elem in channel) send(elem) }\n    }\n}\n\nfun CoroutineScope.numbers(): ReceiveChannel<Int> = produce { repeat(3) { send(it + 1) } }\nfun CoroutineScope.square(numbers: ReceiveChannel<Int>) = produce { for (n in numbers) send(n * n) }\n// for (x in square(numbers())) println(x)   → 1, 4, 9')
    B(C, S, 3, 'p', 'Channel đảm bảo không xung đột (không có vấn đề trạng thái chung) và công bằng, nên hợp làm "băng chuyền" giữa các coroutine: mỗi barista một coroutine nhận đơn từ channel đơn hàng và gửi cà phê vào channel kết quả. Trong thực tế, các trường hợp "giá trị sinh ra ở một bên, xử lý ở bên kia" (sự kiện click, thông báo từ server, kết quả tìm kiếm cập nhật dần) thường hợp với `channelFlow`/`callbackFlow` hơn. Channel thuần hữu ích cho xử lý phức tạp: ví dụ pipeline cập nhật hàng trăm nghìn sản phẩm, với buffer để giới hạn số việc chờ và số coroutine nghe mỗi channel để giới hạn số request đồng thời.', 'Channels guarantee no conflicts (no shared-state problems) and fairness, so they work well as "conveyor belts" between coroutines: each barista is a coroutine taking orders from an orders channel and sending coffees into a results channel. In practice, "values produced on one side, processed on the other" cases (click events, server notifications, gradually updated search results) usually suit `channelFlow`/`callbackFlow` better. Plain channels are useful for complex processing: for example, a pipeline updating hundreds of thousands of offers, with buffers to cap the pending work and the number of coroutines listening on each channel to cap concurrent requests.')

    S = 'select'
    a(C + '.sec.%s.title' % S, 'select: cái nào xong trước', 'select: whichever finishes first')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '`select { }` chờ mệnh đề đầu tiên sẵn sàng: `onAwait` của `Deferred`, `onReceive`/`onReceiveCatching` của channel (có phần tử, hoặc đã đóng), `onSend` (channel còn chỗ). Sách ghi `select` vẫn là API experimental và ít được dùng ([[src:kx-select]]). Ứng dụng thường gặp là race: lấy kết quả nhanh nhất từ nhiều nguồn. Muốn race đúng structured concurrency, chạy các `async` trong `coroutineScope` rồi hủy phần còn lại khi đã có kết quả. Nếu không hủy, `coroutineScope` sẽ chờ cả việc chậm.', '`select { }` waits for the first clause to become ready: a `Deferred`\'s `onAwait`, a channel\'s `onReceive`/`onReceiveCatching` (an element is available, or it is closed), `onSend` (the channel has room). The book notes that `select` is still an experimental API and rarely used ([[src:kx-select]]). The common use is a race: take the fastest result from several sources. To race while respecting structured concurrency, run the `async`s inside `coroutineScope` and cancel the rest once you have a result. Without cancelling, `coroutineScope` would wait for the slow job too.')
    B(C, S, 2, 'kt', 'suspend fun askMultipleForData(): String = coroutineScope {\n    select<String> {\n        async { requestData1() }.onAwait { it }      // 100 s\n        async { requestData2() }.onAwait { it }      // 1 s\n    }.also { coroutineContext.cancelChildren() }      // bỏ việc chậm\n}\n// (1 s) Data2\n\n// nhận từ channel nào có dữ liệu trước\nselect {\n    fooChannel.onReceive { println("From fooChannel: $it") }\n    barChannel.onReceive { println("From barChannel: $it") }\n}', 'suspend fun askMultipleForData(): String = coroutineScope {\n    select<String> {\n        async { requestData1() }.onAwait { it }      // 100 s\n        async { requestData2() }.onAwait { it }      // 1 s\n    }.also { coroutineContext.cancelChildren() }      // drop the slow job\n}\n// (1 s) Data2\n\n// receive from whichever channel has data first\nselect {\n    fooChannel.onReceive { println("From fooChannel: $it") }\n    barChannel.onReceive { println("From barChannel: $it") }\n}')
    B(C, S, 3, 'ask', 'Bỏ `.also { coroutineContext.cancelChildren() }` thì `askMultipleForData()` trả về sau bao lâu? Vì sao?', 'Without `.also { coroutineContext.cancelChildren() }`, how long does `askMultipleForData()` take to return? Why?')
    B(C, S, 3, 'ans', 'Khoảng 100 giây, dù `select` có Data2 sau 1 giây. `coroutineScope` chỉ trả về khi mọi con xong, và `requestData1()` còn chạy. Đây là "cha chờ con" của structured concurrency.', 'About 100 seconds, even though `select` has Data2 after 1 second. `coroutineScope` returns only when all children finish, and `requestData1()` is still running. This is structured concurrency\'s "the parent waits for its children".')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp với channel', 'Common channel bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Màn hình "đang tải" không bao giờ kết thúc: consumer `for (x in channel)` chờ mãi sau khi producer đã lỗi.', 'The "loading" screen never ends: the consumer\'s `for (x in channel)` waits forever after the producer has failed.')
    B(C, S, 1, 'cause', 'Producer tạo bằng `Channel()` + `launch` và gọi `close()` ở cuối khối; exception xảy ra trước dòng đó nên channel không bao giờ đóng.', 'The producer was built with `Channel()` + `launch` and calls `close()` at the end of its block; an exception happens before that line, so the channel never closes.')
    B(C, S, 1, 'fix', 'Dùng `produce { }`: channel được đóng (kèm nguyên nhân lỗi) dù coroutine kết thúc thế nào. Hoặc đặt `close()` trong `finally`.', 'Use `produce { }`: the channel is closed (with the failure cause) however the coroutine ends. Or put `close()` in a `finally`.')
    B(C, S, 2, 'bug', 'Dùng `Channel(Channel.UNLIMITED)` cho luồng sự kiện cảm biến; sau vài phút app bị `OutOfMemoryError`.', 'A `Channel(Channel.UNLIMITED)` carries a sensor event stream; after a few minutes the app hits `OutOfMemoryError`.')
    B(C, S, 2, 'cause', 'Producer nhanh hơn consumer và UNLIMITED không bao giờ làm producer chậm lại (không có back-pressure), nên buffer phình mãi.', 'The producer is faster than the consumer and UNLIMITED never slows the producer down (no back-pressure), so the buffer grows forever.')
    B(C, S, 2, 'fix', 'Chọn sức chứa giới hạn (SUSPEND để producer chờ), hoặc CONFLATED / `DROP_OLDEST` nếu chỉ cần giá trị mới nhất.', 'Choose a bounded capacity (SUSPEND so the producer waits), or CONFLATED / `DROP_OLDEST` if only the latest values matter.')
    B(C, S, 3, 'bug', 'Hai màn hình cùng nghe một channel sự kiện; mỗi màn hình chỉ nhận được "một nửa" số sự kiện.', 'Two screens listen to the same event channel; each screen gets only "half" of the events.')
    B(C, S, 3, 'cause', 'Mỗi phần tử của channel chỉ được nhận MỘT lần (fan-out chia phần tử cho những người nhận), không phải phát cho tất cả.', 'Each channel element is received only ONCE (fan-out splits elements among receivers); it is not broadcast to everyone.')
    B(C, S, 3, 'fix', 'Khi nhiều người cùng cần mọi sự kiện, dùng `SharedFlow` (phát cho mọi subscriber), học ở chương SharedFlow/StateFlow.', 'When several listeners all need every event, use a `SharedFlow` (it broadcasts to every subscriber), covered in the SharedFlow/StateFlow chapter.')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Fan-out: `produceNumbers()` gửi 0..9 mỗi 100 ms; ba processor (#0, #1, #2) khởi động cách nhau 10 ms, mỗi cái `for (msg in channel) println("#$id received $msg")`. Đoán 6 dòng đầu.', 'Fan-out: `produceNumbers()` sends 0..9 every 100 ms; three processors (#0, #1, #2) start 10 ms apart, each doing `for (msg in channel) println("#$id received $msg")`. Predict the first 6 lines.')
    B(C, S, 1, 'sol', '#0 received 0, #1 received 1, #2 received 2, #0 received 3, #1 received 4, #2 received 5. Channel giữ hàng đợi FIFO các coroutine đang chờ: nhận xong thì về cuối hàng.', '#0 received 0, #1 received 1, #2 received 2, #0 received 3, #1 received 4, #2 received 5. The channel keeps a FIFO queue of waiting coroutines: after receiving, each goes to the back of the line.')
    B(C, S, 2, 'ex', 'Bài khuyết bước: pipeline "đọc dòng → parse → lưu DB", trong đó parse chạy song song 4 coroutine và tối đa 100 dòng chờ parse.', 'A partly-solved exercise: a "read lines → parse → save to DB" pipeline, where parsing runs on 4 parallel coroutines and at most 100 lines wait to be parsed.')
    B(C, S, 2, 'hint', '`produce(capacity = 100)` cho dòng; `repeat(4) { launch { for (l in lines) … } }` cho parse (fan-out); một channel kết quả cho phần lưu.', '`produce(capacity = 100)` for the lines; `repeat(4) { launch { for (l in lines) … } }` for parsing (fan-out); one result channel for saving.')
    B(C, S, 2, 'sol', 'Sức chứa 100 tạo back-pressure: đọc file sẽ chờ khi 100 dòng chưa được parse. Bốn coroutine nghe cùng channel dòng thì chia việc công bằng.', 'Capacity 100 creates back-pressure: file reading waits when 100 lines are not yet parsed. Four coroutines on the same lines channel share the work fairly.')
    B(C, S, 2, 'solkt', 'suspend fun importFile(file: File) = coroutineScope {\n    val lines = produce(capacity = 100) { file.useLines { it.forEach { l -> send(l) } } }\n    val records = produce {\n        coroutineScope {\n            repeat(4) { launch { for (l in lines) send(parse(l)) } }\n        }\n    }\n    for (r in records) dao.insert(r)\n}')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'Khi nào `send` suspend, khi nào `receive` suspend? Vì sao nên dùng `produce` thay `Channel()` + `close()`?', 'When does `send` suspend, and when does `receive` suspend? Why prefer `produce` over `Channel()` + `close()`?')
    B(C, S, 1, 'ans', '`send` suspend khi không có chỗ (buffer đầy, hoặc RENDEZVOUS chưa có người nhận); `receive` suspend khi channel rỗng và chưa đóng. `produce` đóng channel trong mọi trường hợp kết thúc, nên consumer không bao giờ chờ mãi vì quên `close()`.', '`send` suspends when there is no room (the buffer is full, or RENDEZVOUS has no receiver yet); `receive` suspends when the channel is empty and not closed. `produce` closes the channel however it ends, so the consumer never waits forever because of a forgotten `close()`.')
    B(C, S, 2, 'ask', 'Channel và SharedFlow khác nhau cơ bản ở đâu khi có nhiều người nghe?', 'What is the basic difference between a Channel and a SharedFlow when there are several listeners?')
    B(C, S, 2, 'ans', 'Channel: mỗi phần tử tới đúng MỘT người nhận (chia việc). SharedFlow: mỗi giá trị phát tới MỌI subscriber (phát sóng).', 'Channel: each element goes to exactly ONE receiver (work splitting). SharedFlow: each value goes to EVERY subscriber (broadcast).')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'Channel mặc định (`Channel<Int>()`) có sức chứa bao nhiêu?', 'What is the capacity of a default channel (`Channel<Int>()`)?',
         '0 (RENDEZVOUS).', '0 (RENDEZVOUS).', 'Mỗi `send` phải gặp một `receive`.', 'Every `send` must meet a `receive`.'),
        ('q2', 'CONFLATED tương đương cấu hình nào?', 'Which configuration is CONFLATED equivalent to?',
         'Sức chứa 1 + `onBufferOverflow = DROP_OLDEST`.', 'Capacity 1 + `onBufferOverflow = DROP_OLDEST`.', 'Phần tử mới thay phần tử cũ chưa nhận.', 'The new element replaces the old, unreceived one.'),
        ('q3', 'Ba coroutine cùng `for (x in channel)`: một phần tử được mấy coroutine nhận?', 'Three coroutines all do `for (x in channel)`: how many of them receive a given element?',
         'Đúng một.', 'Exactly one.', 'Channel chia phần tử theo hàng đợi FIFO các coroutine đang chờ.', 'A channel splits elements over a FIFO queue of waiting coroutines.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
